(function () {
  const q = s => document.querySelector(s);
  function freezeRect(win, parent) {
    if (!win || !parent) return;
    const wr = win.getBoundingClientRect(), pr = parent.getBoundingClientRect();
    const margin = 16;
    let x = Math.round(wr.left - pr.left + parent.scrollLeft);
    let y = Math.round(wr.top - pr.top + parent.scrollTop);
    const w = Math.round(wr.width), h = Math.round(wr.height);
    const maxX = Math.max(margin, parent.clientWidth - w - margin);
    const maxY = Math.max(margin, parent.clientHeight - h - margin);
    x = Math.max(margin, Math.min(x, maxX));
    y = Math.max(margin, Math.min(y, maxY));
    win.classList.add('drag-free');
    win.style.setProperty('position', 'absolute', 'important');
    win.style.setProperty('left', x + 'px', 'important');
    win.style.setProperty('top', y + 'px', 'important');
    win.style.setProperty('right', 'auto', 'important');
    win.style.setProperty('bottom', 'auto', 'important');
    win.style.setProperty('width', w + 'px', 'important');
    win.style.setProperty('height', h + 'px', 'important');
  }
  window.primeStepWindows = function (step) {
    const prime = (win, parent) => freezeRect(win, parent);
    if (step === 2) {
      const parent = q('#captureDesktop');
      if (!parent) return;
      parent.style.position = 'relative';
      parent.style.overflow = 'visible';
      parent.classList.add('clq-step2-frozen');
      const width = Math.max(
        1160,
        parent.clientWidth
      );
      parent.style.setProperty(
        'width',
        `${width}px`,
        'important'
      );
      const preview = q('#capturePreviewWindow');
      const main = q('#mainWindow');
      const filters = q('#controlWindow');
      const gap = 25;
      const side = 300;
      const previewWidth = 300;
      const mainWidth = Math.max(
        500,
        width - previewWidth - side - gap * 2
      );
      const controlLeft = Math.max(
        previewWidth + gap + mainWidth + gap,
        width - side - 16
      );
      const place = (win, left, top, w) => {
        if (!win) return;
        win.classList.add('drag-free');
        win.style.setProperty('position', 'absolute', 'important');
        win.style.setProperty('left', `${left}px`, 'important');
        win.style.setProperty('top', `${top}px`, 'important');
        win.style.setProperty('right', 'auto', 'important');
        win.style.setProperty('bottom', 'auto', 'important');
        win.style.setProperty('width', `${w}px`, 'important');
        win.style.setProperty('min-width', `${w}px`, 'important');
        win.style.setProperty('max-width', `${w}px`, 'important');
        win.style.setProperty('height', 'auto', 'important');
      };
      place(preview, 16, 16, previewWidth);
      place(main, 16 + previewWidth + gap, 16, mainWidth);
      place(filters, controlLeft, 16, side);
      parent.style.setProperty(
        'height',
        `${Math.max(
          760,
          Math.max(
            preview?.offsetHeight || 0,
            main?.offsetHeight || 0,
            filters?.offsetHeight || 0
          ) + 32
        )}px`,
        'important'
      );
      if (filters) {
        filters.style.setProperty('overflow', 'visible', 'important');
        const body = filters.querySelector('.window-body');
        if (body) body.style.setProperty('overflow', 'auto', 'important');
      }
      return;
    }
    if (step === 3) {
      const parent = document.querySelector('.custom-layout');
      if (parent) {
        parent.style.position = 'relative'; parent.style.overflow = 'visible';
        parent.style.setProperty(
          'width',
          `${Math.max(1240, parent.clientWidth)}px`,
          'important'
        );
        prime(document.querySelector('.customize-preview'), parent);
        prime(q('#stickerWindow'), parent); prime(q('#styleWindow'), parent); prime(q('#frameWindow'), parent);
        const preview = document.querySelector('.customize-preview');
        const place = (win, left, top) => {
          if (!win) return;
          win.style.setProperty('left', `${left}px`, 'important');
          win.style.setProperty('top', `${top}px`, 'important');
        };
        place(q('#stickerWindow'), 16, 16);
        place(q('#styleWindow'), 16, 450);
        place(preview, 270, 16);
        place(q('#frameWindow'), (preview?.offsetLeft || 270) + (preview?.offsetWidth || 690) + 24, 16);
      }
      return;
    }
    if (step === 4) {
      const parent = document.querySelector('.download-layout');
      if (parent) { parent.style.position = 'relative'; parent.style.overflow = 'visible'; prime(q('#downloadWindow'), parent); }
    }
  };
})();


